(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.03+t*0.15)*8+Math.cos((y+wy1)*0.025-t*0.1)*6;
  const wy2 = Math.cos((y+wy1)*0.03-t*0.2)*8+Math.sin((x+wx1)*0.028+t*0.18)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+1)*60,220+Math.sin(t*0.75+4)*40,0.085,1.8,1.05]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.cos(d*f*1.3-t*sp*0.8+2.0)*w;
  }
  const act=aS/8,inh=iS/8,cross=cS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2
    +Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.06-t*0.7)*0.3;
  const cx=240,cy=120;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08-ang*2+t*0.8)*Math.cos(dist*0.06+ang*5-t*1.0)*0.2;
  const micro=Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.25-sy*0.35-t*2.5)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2)*2.2+cross*0.4);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.65+cell*0.2+micro*0.15, v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[12,45,85],[20,90,120],[30,140,130],
    [80,175,120],[160,195,80],[220,180,60],[230,130,55],
    [200,80,60],[150,45,70],[90,25,65],[40,15,50],[5,12,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.12:1.0;
  const shimmer=1.0+Math.sin(cross*3+t*4)*0.05;
  const br=lum*edge*shimmer;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*br)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*br)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*br)|0
  ];
}
